class Kisi:
    def __init__(self, ad, yas):
        self.ad = ad
        self.yas = yas

    def __str__(self):
        return f"{self.ad} ({self.yas})"

print(Kisi("Ali", 30))

def log(f):
    def sar():
        print("önce")
        f()
        print("sonra")
    return sar

@log
def calis():
    print("çalış")

calis()

